#!/usr/bin/env python3
"""Build a self-contained presentation from local source files. No dependencies."""

from pathlib import Path
import base64
import json
import re

ROOT = Path(__file__).resolve().parents[1]


def data_url(path: Path) -> str:
    mime = {'.woff2': 'font/woff2', '.svg': 'image/svg+xml'}[path.suffix]
    return f'data:{mime};base64,' + base64.b64encode(path.read_bytes()).decode()


def embed_css(match: re.Match) -> str:
    path = ROOT / match.group(1)
    css = path.read_text()

    def embed_url(url_match):
        relative = url_match.group(1).strip('"\'')
        file = path.parent / relative
        if file.is_file():
            return f'url("{data_url(file)}")'
        return url_match.group(0)

    css = re.sub(r'url\(([^)]+)\)', embed_url, css)
    # WOFF2 is embedded for all modern browsers; drop unused WOFF/TTF fallbacks.
    css = re.sub(r',url\([^)]*\.(?:woff|ttf)\) format\("[^"]+"\)', '', css)
    return '<style>\n' + css + '\n</style>'


def script_tag(source: str, module: bool = False) -> str:
    source = re.sub(r'//# sourceMappingURL=.*', '', source)
    source = source.replace('</script', '<\\/script')
    return '<script' + (' type="module"' if module else '') + '>\n' + source + '\n</script>'


def main():
    html = (ROOT / 'index.html').read_text()
    html = re.sub(r'<link rel="stylesheet" href="([^"]+)">', embed_css, html)
    html = html.replace('href="assets/favicon.svg"', f'href="{data_url(ROOT / "assets/favicon.svg")}"')
    html = re.sub(r'<script src="([^"]+)"></script>', lambda m: script_tag((ROOT / m.group(1)).read_text()), html)
    scripts = []
    for name in ['drawing.js', 'figures.js', 'transitions.js', 'deck.js']:
        source = (ROOT / 'js' / name).read_text()
        source = re.sub(r'^import .*?;\s*$', '', source, flags=re.M)
        source = re.sub(r'^export ', '', source, flags=re.M)
        scripts.append(source)
    data = json.dumps({
        'markdown': (ROOT / 'slides.md').read_text(),
        'hopfield': json.loads((ROOT / 'assets/hopfield.json').read_text()),
    }, ensure_ascii=False).replace('<', '\\u003c')
    payload = '<script type="application/json" id="embedded-content">' + data + '</script>\n'
    html = html.replace('<script type="module" src="js/deck.js"></script>', payload + script_tag('\n'.join(scripts), module=True))
    html = html.replace('<head>', '<head>\n<!-- Generated by scripts/build.py. Edit the source files, then rebuild. -->', 1)
    destination = ROOT / 'presentation.html'
    destination.write_text(html)
    print(f'Built {destination.name} ({destination.stat().st_size:,} bytes); scripts, fonts, diagrams, and notes are embedded.')


if __name__ == '__main__':
    main()
